-- redash #120276
-- Database: _EDW BI

-- Aging Analysis Query

-- Objective: The following query is used to identify the first period where an event had a negative balance. 

-- Inputs: The user should have a set of bank transaction ids that they want to look up. In the context of using this with the 
-- Netting analysis, the bank_transaction_ids there should provide the user with the bts to add to the IN clause 

-- Parameters:
-- bank_transaction_date - cutoff date for company balances data for the first month (the last day of the month the user is analyzing)



WITH cte AS (
    SELECT 
        abh.pr_on_behalf_of_id,
        event_id || 'x' || transaction_category AS concat,
        CASE 
            WHEN abh.bank_transaction_date < '2020-01-01'::date THEN abh.bank_transaction_date::date
            ELSE abh.bank_transaction_date
        END AS bank_transaction_date,
        abh.investigation_status,
        abh.investigation_created_at::date AS investigation_date,
        SUM(abh.balance) AS balance
    FROM bi_reporting.accounting_balance_history abh
    WHERE abh.bank_transaction_date <= '{{ bank_transaction_date }}'
    GROUP BY 1, 2, 3, 4, 5
),
cte2 AS (
    SELECT 
        cte.concat AS uid,--Manjari Fixed it 
        cte.pr_on_behalf_of_id,
        cte.bank_transaction_date,
        SUM(cte.balance) AS balance
    FROM cte
    GROUP BY 1, 2, 3
),
cumulative_balance AS (
    SELECT 
        uid,
        pr_on_behalf_of_id,
        bank_transaction_date,
        SUM(balance) OVER (
            PARTITION BY uid 
            ORDER BY bank_transaction_date 
            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
        ) AS running_balance
    FROM cte2
),
first_negative AS (
    SELECT 
        uid,
        bank_transaction_date AS negative_balance_date,
        running_balance,
        ROW_NUMBER() OVER (PARTITION BY uid ORDER BY bank_transaction_date) AS rn
    FROM cumulative_balance
    WHERE running_balance < 0
    
)
SELECT 
    uid,
    negative_balance_date,
    running_balance
FROM first_negative
WHERE rn = 1
and uid IN ('7757500913179702xTax Payment',
'7757500955229459xTax Payment',
